// EDIT ME: only = key ids to write in this run
const only = [972784683, 972784682];
const tags = ['PDFHELP-2648', 'PDFHELP-2644', 'usage-stats'];
const d = function (label, what) { return 'Landing pages (PDF editor, Sign PDF and other tool landings): usage stats row under the upload box. The number of documents ' + what + ', shown above the label "' + label + '". Write it with your locale\'s decimal separator and its usual short form for million / thousand (e.g. IT "1,6 Mln"). Keep it short: it sits in a narrow stat column. PDFHELP-2648'; };
const all = [
  { key_id: 972784684, description: d('Documents uploaded', 'uploaded'), tags: tags },
  { key_id: 972784683, description: d('Documents edited', 'edited'), tags: tags },
  { key_id: 972784682, description: d('Documents converted', 'converted'), tags: tags }
];
const keys = all.filter(function (k) { return only.indexOf(k.key_id) !== -1; });
return [{ json: { project_id: '479073796a6095e8c10e35.09051894', ids: keys.map(function (k) { return k.key_id; }).join(','), keys: keys } }];

const p = $('Params').first().json; const cur = {}; for (const k of ($input.first().json.keys || [])) { cur[k.key_id] = k; }
const out = []; const skipped = [];
for (const w of p.keys) {
  const c = cur[w.key_id]; if (!c) { skipped.push({ key_id: w.key_id, why: 'not found' }); continue; }
  if (c.is_archived) { skipped.push({ key_id: w.key_id, why: 'archived' }); continue; }
  const item = { key_id: w.key_id };
  if (!c.description || !String(c.description).trim()) { item.description = w.description; } else { skipped.push({ key_id: w.key_id, why: 'description not empty' }); }
  const have = c.tags || []; const add = w.tags.filter(function (t) { return have.indexOf(t) === -1; });
  if (add.length) { item.tags = add; item.merge_tags = true; }
  if (item.description || item.tags) { out.push(item); }
}
if (!out.length) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, before: p.keys.map(function (w) { const c = cur[w.key_id] || {}; return { key_id: w.key_id, tags: c.tags, description: c.description }; }) } }];

const b = $('Build').first().json; const after = {}; for (const k of ($input.first().json.keys || [])) { after[k.key_id] = k; }
const res = [];
for (const w of $('Params').first().json.keys) {
  const a = after[w.key_id] || {}; const before = (b.before.find(function (x) { return x.key_id === w.key_id; }) || {}).tags || [];
  res.push({ key_id: w.key_id, name: a.key_name && a.key_name.web, description_ok: a.description === w.description, new_tags_ok: w.tags.every(function (t) { return (a.tags || []).indexOf(t) !== -1; }), old_tags_kept: before.every(function (t) { return (a.tags || []).indexOf(t) !== -1; }), tags: a.tags });
}
return [{ json: { summary_marker: true, skipped: b.skipped, results: res } }];
